class Solution {
public:
    int maxValidPairSum(vector<int>& nums,int k){
        long long ans=LLONG_MIN;
        int best=INT_MIN;
        for(int j=k;j<(int)nums.size();++j){
            best=max(best,nums[j-k]);
            ans=max(ans,1LL*best+nums[j]);
        }
        return (int)ans;
    }
};
